import{_ as A,C as n,o as E,c as l,a2 as o,b as e,w as r,a,E as s,a3 as B}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"Hearth 自进化机制设计说明","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/Hearth-自进化机制设计说明.md","filePath":"architecture/Hearth-自进化机制设计说明.md","lastUpdated":null}'),g={name:"architecture/Hearth-自进化机制设计说明.md"};function i(c,t,h,p,_,D){const d=n("Mermaid");return E(),l("div",null,[t[3]||(t[3]=o('<h1 id="hearth-自进化机制设计说明" tabindex="-1">Hearth 自进化机制设计说明 <a class="header-anchor" href="#hearth-自进化机制设计说明" aria-label="Permalink to &quot;Hearth 自进化机制设计说明&quot;">​</a></h1><blockquote><p><strong>阅读范围</strong>：本文只依据项目源码整理（<code>apps/server/src</code>、<code>packages/*/src</code>），未参考 <code>docs/</code> 与 <code>README.md</code>。 <strong>表达方式</strong>：只讲设计思路与运行机制，不粘贴任何项目源码；文中括号内的文件名仅用于定位核对。 <strong>整理日期</strong>：2026-11-13</p></blockquote><hr><h2 id="_0-一句话看懂" tabindex="-1">0. 一句话看懂 <a class="header-anchor" href="#_0-一句话看懂" aria-label="Permalink to &quot;0. 一句话看懂&quot;">​</a></h2><p>这套「自进化」<strong>不是训练或微调模型</strong>，而是把每一次任务留下的经验，做成可积累的外部资产，再在下一轮提示词里喂回去。</p><p>模型权重从头到尾不变，变的是「任务前后拼接的上下文」和「可复用的流程建议」。所有状态都通过事件溯源写进本地 SQLite（只有技能包额外落成 <code>SKILL.md</code> 文件），因此天然可审计、可回放、可回滚。</p><p>它的整体形状是一个挂在任务生命周期上的闭环：</p>',7)),(E(),e(B,null,{default:r(()=>[s(d,{id:"mermaid-21",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%22%E4%BB%BB%E5%8A%A1%E6%89%A7%E8%A1%8C%3Cbr%2F%3E%E8%B7%91%E4%B8%80%E6%AC%A1%E7%9C%9F%E5%AE%9E%E5%B7%A5%E4%BD%9C%22%5D%20--%3E%20B%5B%22%E8%BD%A8%E8%BF%B9%E7%95%99%E7%97%95%3Cbr%2F%3E%E5%B7%A5%E5%85%B7%20%2F%20%E5%86%B3%E7%AD%96%20%2F%20%E5%A4%B1%E8%B4%A5%20%2F%20%E8%AF%8A%E6%96%AD%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22%E8%87%AA%E5%8A%A8%E6%B2%89%E6%B7%80%3Cbr%2F%3E%E7%BB%8F%E9%AA%8C%E8%AE%B0%E5%BF%86%20%C2%B7%20%E5%A4%8D%E7%9B%98%E6%96%B9%E6%B3%95%20%C2%B7%20%E4%B8%AA%E4%BA%BA%E6%9C%AC%E4%BD%93%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22%E5%9B%9E%E6%B5%81%E6%B3%A8%E5%85%A5%3Cbr%2F%3E%E6%8B%BC%E8%BF%9B%E4%B8%8B%E4%B8%80%E8%BD%AE%E6%8F%90%E7%A4%BA%E8%AF%8D%22%5D%0A%20%20%20%20D%20-.-%3E%7C%22%E4%B8%8A%E4%B8%80%E8%BD%AE%E7%9A%84%E7%BB%8F%E9%AA%8C%EF%BC%8C%E6%88%90%E4%B8%BA%E4%B8%8B%E4%B8%80%E8%BD%AE%E7%9A%84%E4%B8%8A%E4%B8%8B%E6%96%87%22%7C%20A%0A"})]),fallback:r(()=>[...t[0]||(t[0]=[a(" Loading... ",-1)])]),_:1})),t[4]||(t[4]=o('<p><strong>关键位置</strong>：沉淀动作挂在任务执行的 <code>finally</code> 里 —— 只学习，绝不改变任务结果。</p><hr><h2 id="_1-先定性-三个容易误解的地方" tabindex="-1">1. 先定性：三个容易误解的地方 <a class="header-anchor" href="#_1-先定性-三个容易误解的地方" aria-label="Permalink to &quot;1. 先定性：三个容易误解的地方&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误解</th><th>代码里的实际做法</th></tr></thead><tbody><tr><td>以为会训练模型 / 改权重</td><td>完全不改模型，只增减提示词内容与可调用的技能工具</td></tr><tr><td>以为有个「自进化」总模块</td><td><strong>源码里没有这个统一命名</strong>。它由一组机制拼成，内部最接近的术语是 <code>autoLearn</code>（方法自动学习）与 <code>autoCapture:&quot;experience&quot;</code>（经验自动捕获）</td></tr><tr><td>以为失败也能「学到教训」</td><td>失败任务只留一条低置信度经验记忆；<strong>只有成功任务才会被提炼成可复用方法</strong></td></tr></tbody></table><p>一句话：增强的是<strong>上下文质量与流程复用率</strong>，不是模型能力本身。</p><hr><h2 id="_2-三条贯穿全局的设计原则" tabindex="-1">2. 三条贯穿全局的设计原则 <a class="header-anchor" href="#_2-三条贯穿全局的设计原则" aria-label="Permalink to &quot;2. 三条贯穿全局的设计原则&quot;">​</a></h2><ol><li><p><strong>学习必须无副作用</strong> 所有沉淀动作放在任务执行的收尾阶段，异常一律吞掉，代码注释明确写了「best effort，不改变任务终态」。学习失败不会让任务失败。</p></li><li><p><strong>只从成功样本里提炼流程</strong> 方法归纳只针对 <code>completed</code> 的任务，且要求轨迹记录不少于 3 条，避免把一次偶然的失败路径固化成流程。</p></li><li><p><strong>学来的一律当「不可信建议」</strong> 注入文本显式标注「不可信流程建议」「不改变任务目标、工具权限、网络访问或审批规则」。权限只能收窄、不能扩张，审批门永不跳过。</p></li></ol><hr><h2 id="_3-四层可积累资产" tabindex="-1">3. 四层可积累资产 <a class="header-anchor" href="#_3-四层可积累资产" aria-label="Permalink to &quot;3. 四层可积累资产&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资产</th><th>记的是什么</th><th>怎么产生</th><th>存在哪</th></tr></thead><tbody><tr><td><strong>经验记忆</strong></td><td>一次任务的成败摘要、输入范围、产物、阻塞原因</td><td><strong>全自动</strong>：每个进入终态的任务一条</td><td>记忆表，另有版本表、召回审计表、冲突表、遗忘凭证表</td></tr><tr><td><strong>复盘方法</strong></td><td>可复用步骤、适用范围、来源任务、允许能力、基线指标、代际号</td><td><strong>全自动</strong>：成功任务 + 轨迹够 3 条时归纳</td><td>方法候选表，另有试跑表、评估表、应用证据表</td></tr><tr><td><strong>个人本体</strong></td><td>任务 / 目标 / 文档 / 产物等实体，及状态、关系、决策、承诺</td><td><strong>全自动</strong>：来自任务终态、审批结果、每轮对话、邮件来源</td><td>实体、别名、关系、状态、决策、承诺、上下文包等表</td></tr><tr><td><strong>技能包</strong></td><td>方法固化成带权限清单的标准文档</td><td><strong>仅手动导出</strong>：唯一落文件的资产</td><td>技能表 + 版本表 + 磁盘上的 <code>SKILL.md</code></td></tr></tbody></table><blockquote><p>另有一个很轻的反馈环：用户对主动提醒的「接受 / 忽略 / 判断有误」会调整推送评分，但它调的是<strong>提醒优先级</strong>，不属于能力资产。</p></blockquote><h3 id="_3-1-每条资产都带「出身与信任标签」" tabindex="-1">3.1 每条资产都带「出身与信任标签」 <a class="header-anchor" href="#_3-1-每条资产都带「出身与信任标签」" aria-label="Permalink to &quot;3.1 每条资产都带「出身与信任标签」&quot;">​</a></h3><p>记忆不是一段纯文本，而是带了一整套治理字段：来源类别（用户 / 系统验证 / Agent 生成 / 导入 / 网页 / 邮件 / 不可信）、信任等级、污染状态、敏感度、层级（指令 / 策展 / 情景 / 前瞻 / 待复核）、置信度、重要性、有效期、内容哈希、召回次数等。这些字段直接决定它后面能不能被召回、能不能被合并。</p><h3 id="_3-2-方法与技能都有「代际」概念" tabindex="-1">3.2 方法与技能都有「代际」概念 <a class="header-anchor" href="#_3-2-方法与技能都有「代际」概念" aria-label="Permalink to &quot;3.2 方法与技能都有「代际」概念&quot;">​</a></h3><p>方法状态机：候选 → 评估中 → 试跑 → 已采纳 / 已拒绝 / 已回退 / 已取代。 新方法一经采纳，同模板下的旧方法被标为「已取代」，代际号递增，形成一条可回退的版本链。技能也有版本、置顶标记、归档原因与恢复入口。</p><hr><h2 id="_4-完整数据流-从一次执行到一条资产" tabindex="-1">4. 完整数据流：从一次执行到一条资产 <a class="header-anchor" href="#_4-完整数据流-从一次执行到一条资产" aria-label="Permalink to &quot;4. 完整数据流：从一次执行到一条资产&quot;">​</a></h2>',18)),(E(),e(B,null,{default:r(()=>[s(d,{id:"mermaid-192",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20S%5B%22%E4%BB%BB%E5%8A%A1%E6%89%A7%E8%A1%8C%E4%B8%AD%22%5D%20--%3E%20R%5B%22%E9%80%90%E6%9D%A1%E7%95%99%E7%97%95%EF%BC%9A%E5%B7%A5%E5%85%B7%E8%B0%83%E7%94%A8%20%2F%20%E5%86%B3%E7%AD%96%20%2F%20%E5%A4%B1%E8%B4%A5%20%2F%20%E8%AF%8A%E6%96%AD%20%2F%20%E5%8F%AC%E5%9B%9E%3Cbr%2F%3E%E5%86%99%E5%85%A5%E8%BD%A8%E8%BF%B9%E8%A1%A8%20%2B%20%E8%BF%BD%E5%8A%A0%E4%BA%8B%E4%BB%B6%22%5D%0A%20%20%20%20R%20--%3E%20F%7B%22%E4%BB%BB%E5%8A%A1%E7%BB%93%E6%9D%9F%20finally%22%7D%0A%20%20%20%20F%20--%3E%20L%5B%22%E2%91%A0%20%E5%AD%A6%E4%B9%A0%E6%96%B9%E6%B3%95%20%E6%88%96%20%E8%AE%B0%E5%BD%95%E8%AF%95%E8%B7%91%E8%AF%81%E6%8D%AE%22%5D%0A%20%20%20%20F%20--%3E%20M%5B%22%E2%91%A1%20%E6%8D%95%E8%8E%B7%E7%BB%8F%E9%AA%8C%E8%AE%B0%E5%BF%86%22%5D%0A%20%20%20%20F%20--%3E%20O%5B%22%E2%91%A2%20%E5%9B%9E%E5%86%99%E4%B8%AA%E4%BA%BA%E6%9C%AC%E4%BD%93%22%5D%0A%20%20%20%20L%20--%3E%20P%5B%22%E5%BD%92%E7%BA%B3%E6%AD%A5%E9%AA%A4%20%E2%86%92%20%E6%8C%87%E7%BA%B9%E5%88%A4%E9%87%8D%20%E2%86%92%20%E9%87%87%E7%BA%B3%20%2F%20%E5%A4%8D%E7%94%A8%22%5D%0A%20%20%20%20M%20--%3E%20Q%5B%22%E6%8C%89%E6%9D%A5%E6%BA%90%E4%BB%BB%E5%8A%A1%E5%88%A4%E9%87%8D%20%E2%86%92%20%E5%AE%9A%E7%BD%AE%E4%BF%A1%E5%BA%A6%22%5D%0A%20%20%20%20O%20--%3E%20T%5B%22%E5%AE%9E%E4%BD%93%E5%88%A4%E9%87%8D%E5%90%88%E5%B9%B6%20%E2%86%92%20%E7%8A%B6%E6%80%81%E5%86%B2%E7%AA%81%E8%BD%AC%E4%BA%BA%E5%B7%A5%22%5D%0A%20%20%20%20P%20--%3E%20U%5B%22%E8%B5%84%E4%BA%A7%E8%A1%A8%20%2B%20%E4%BA%8B%E4%BB%B6%E6%97%A5%E5%BF%97%22%5D%0A%20%20%20%20Q%20--%3E%20U%0A%20%20%20%20T%20--%3E%20U%0A%20%20%20%20U%20--%3E%20V%5B%22%E4%B8%8B%E4%B8%80%E8%BD%AE%E4%BB%BB%E5%8A%A1%EF%BC%9A%E5%9B%9B%E6%9D%A1%E9%80%9A%E9%81%93%E5%8F%AC%E5%9B%9E%E6%B3%A8%E5%85%A5%22%5D%0A%20%20%20%20V%20-.-%3E%20S%0A"})]),fallback:r(()=>[...t[1]||(t[1]=[a(" Loading... ",-1)])]),_:1})),t[5]||(t[5]=o('<p><strong>逐环节说明：</strong></p><p><strong>① 留痕</strong> 工具调用、决策、失败、诊断、记忆召回、方法注入等，都会逐条写进轨迹表，同时追加为事件。这是所有学习动作的原料。</p><p><strong>② 触发（唯一的自动汇聚点）</strong> 任务执行收尾时，依次调用三件事：学习方法（或记录试跑证据）、捕获经验、回写本体。三者都在保护块里，互不影响，也不影响任务终态。</p><p><strong>③ 归纳与判重</strong></p><ul><li><strong>方法</strong>：把轨迹拼成「核对输入范围 → 关键工具顺序 → 关键决策与失败 → 生成期望产物 → 发布前保留原有审批门」这样的步骤；再用「模板 + 输入结构 + 步骤 + 能力」算出一个指纹，命中已有且未被拒绝/回退的就直接复用，不重复创建。</li><li><strong>经验</strong>：按来源任务 ID 判重；成功的给中置信度，失败的给低置信度。</li><li><strong>本体</strong>：按名称 / 别名合并实体；同值状态合并证据引用；一旦出现互相矛盾的状态值，不自动覆盖，而是生成一条待办交人工确认。</li></ul><p><strong>④ 巩固与淘汰</strong></p><ul><li><strong>记忆巩固</strong>（手动）：按「作用域 + 主题键」分桶，同主题至少 2 条才成组，按重要性、置信度、信任、召回次数、跨天数打分排序；有新记忆生成、旧记忆标为「已被取代」并关闭召回，整批事件原子提交。</li><li><strong>技能整理</strong>（自动）：唯一的资产类定时器，每小时检查一次，但真正动手要满足「距上次整理满 7 天」且「系统空闲满 2 小时」。14 天未用标记过时并退出日常索引，30 天未用归档但保留恢复入口；只处理自动生成、未置顶、未被定时任务引用的技能。首次运行只记录基线、不改任何状态。动作前写快照备份，支持一键回滚。</li></ul><hr><h2 id="_5-经验怎么影响下一次任务-四条注入通道" tabindex="-1">5. 经验怎么影响下一次任务：四条注入通道 <a class="header-anchor" href="#_5-经验怎么影响下一次任务-四条注入通道" aria-label="Permalink to &quot;5. 经验怎么影响下一次任务：四条注入通道&quot;">​</a></h2><table tabindex="0"><thead><tr><th>通道</th><th>检索逻辑</th><th>注入方式</th></tr></thead><tbody><tr><td><strong>记忆</strong></td><td>两级召回：<strong>常驻层</strong>（指令 / 策展级 + 信任达标，最多 3 条、占 40% 字符预算）；<strong>按需层</strong>（综合置信度、信任、层级、作用域、实体图关联、词法匹配、新鲜度、历史召回次数打分）。整体受最大条数与最大字数约束</td><td>生成上下文包，拼进任务首轮提示词</td></tr><tr><td><strong>方法</strong></td><td>按任务模板自动匹配最新「已采纳」的方法，或用户手动置顶的那个</td><td>渲染成「可复用方法（不可信流程建议）」块；先过滤含「跳过 / 绕过审批」字样的危险步骤，再拼进提示词</td></tr><tr><td><strong>个人本体</strong></td><td>上下文代理按查询匹配实体，带出状态、关系、决策、承诺</td><td>编译成个人上下文包，按「必知 / 相关 / 可回想 / 省略」分层并受 token 预算约束</td></tr><tr><td><strong>技能</strong></td><td>只对「已采纳」的技能，或处于试跑且试跑任务列表命中当前任务的技能开放</td><td>提供技能索引 + 按需加载工具；加载时校验内容哈希与执行权限</td></tr></tbody></table><p><strong>两个值得留意的小设计：</strong></p><ul><li><strong>召回会自我强化</strong>：每次记忆被召回都写一条审计，并累加该记忆的召回次数；这个计数又成为下次打分的输入 —— 被用得多的记忆更容易再被选中。</li><li><strong>注入要留凭据</strong>：只有当提示词里<strong>确实包含</strong>那段方法文本时，才记录一条「应用证据」（带提示词哈希、方法版本、选择方式）；若因续接或预算限制没注入，则改记一条说明。这是为后续做 A/B 评估刻意准备的可验证凭据，避免「以为用了方法其实没用」。</li></ul><hr><h2 id="_6-安全闸门-这套设计里最用力的部分" tabindex="-1">6. 安全闸门（这套设计里最用力的部分） <a class="header-anchor" href="#_6-安全闸门-这套设计里最用力的部分" aria-label="Permalink to &quot;6. 安全闸门（这套设计里最用力的部分）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类别</th><th>具体做法</th></tr></thead><tbody><tr><td><strong>权限不扩张</strong></td><td>方法声明的能力必须落在「所有来源任务能力的交集」内，创建、评估、采纳三处分别复检；技能执行权限取「技能 ∩ 任务」的交集，还会扫描文档里是否夹带越权指令</td></tr><tr><td><strong>内容不可信</strong></td><td>注入文本统一声明「不改变权限或审批规则」；危险步骤用规则过滤；技能文档有固定章节校验与内容哈希校验</td></tr><tr><td><strong>治理过滤</strong></td><td>污染、不可信来源、信任为 none、机密级、已过期、待复核层级的记忆，一律排除在召回与巩固之外；常驻层还额外要求信任达标</td></tr><tr><td><strong>试跑有门槛</strong></td><td>试跑样本要求：任务确实注入过该方法、版本一致、对应运行记录存在、且<strong>没有外部副作用</strong></td></tr><tr><td><strong>冲突转人工</strong></td><td>记忆巩固遇到内容冲突直接跳过并提示人工确认；本体状态冲突生成待办；验收判官可返回「需要人工」</td></tr><tr><td><strong>默认可撤销</strong></td><td>记忆巩固默认是 dry-run（只出报告不落库）；技能整理有快照备份与回滚；方法有代际、取代、回退；记忆有遗忘凭证与墓碑</td></tr></tbody></table><blockquote><p>一个略反直觉的细节：<code>autoLearn</code> 与 <code>autoCapture</code> <strong>不允许关闭</strong> —— 设置里改成 false 会被强制改回开启，代码里对应「自动学习始终开启」的报错。</p></blockquote><hr><h2 id="_7-最值得注意的一点-这是个「半闭环」" tabindex="-1">7. 最值得注意的一点：这是个「半闭环」 <a class="header-anchor" href="#_7-最值得注意的一点-这是个「半闭环」" aria-label="Permalink to &quot;7. 最值得注意的一点：这是个「半闭环」&quot;">​</a></h2><p>代码里其实存在<strong>两条</strong>通往「采纳」的路径，但只有一条被接进自动链：</p>',19)),(E(),e(B,null,{default:r(()=>[s(d,{id:"mermaid-395",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20subgraph%20FAST%5B%22%E8%87%AA%E5%8A%A8%E5%BF%AB%E9%80%9A%E9%81%93%20%C2%B7%20%E5%AE%9E%E9%99%85%E8%BF%90%E8%A1%8C%22%5D%0A%20%20%20%20%20%20%20%20F1%5B%22%E4%BB%BB%E5%8A%A1%E6%88%90%E5%8A%9F%20%2B%20%E8%BD%A8%E8%BF%B9%E2%89%A53%22%5D%20--%3E%20F2%5B%22%E5%BD%92%E7%BA%B3%E5%B9%B6%E6%8C%87%E7%BA%B9%E5%88%A4%E9%87%8D%22%5D%20--%3E%20F3%5B%22%E7%9B%B4%E6%8E%A5%E6%A0%87%E8%AE%B0%E5%B7%B2%E9%87%87%E7%BA%B3%3Cbr%2F%3E%E6%97%A0%E9%9C%80%E5%AF%B9%E6%AF%94%E8%AF%81%E6%8D%AE%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20SLOW%5B%22%E4%BA%BA%E5%B7%A5%E4%B8%A5%E8%B0%A8%E9%80%9A%E9%81%93%20%C2%B7%20%E4%BB%85%20REST%20%E6%8E%A5%E5%8F%A3%EF%BC%8C%E6%9C%AA%E6%8E%A5%E8%87%AA%E5%8A%A8%E8%B0%83%E5%BA%A6%22%5D%0A%20%20%20%20%20%20%20%20S1%5B%22%E5%80%99%E9%80%89%E6%96%B9%E6%B3%95%3Cbr%2F%3E%E8%AE%B0%E5%BD%95%E8%AF%95%E8%B7%91%E8%AF%81%E6%8D%AE%22%5D%20--%3E%20S2%5B%22%E5%9F%BA%E7%BA%BF%20%2F%20%E8%AF%95%E8%B7%91%20A%2FB%3Cbr%2F%3E%E5%90%8C%E6%A8%A1%E6%9D%BF%E3%80%81%E5%90%84%E2%89%A52%20%E6%A0%B7%E6%9C%AC%22%5D%20--%3E%20S3%5B%22%E5%88%A4%E5%AE%9A%20%E6%94%B9%E8%BF%9B%20%2F%20%E6%8C%81%E5%B9%B3%20%2F%20%E9%80%80%E6%AD%A5%3Cbr%2F%3E%E6%88%90%E5%8A%9F%E7%8E%87%20%2B%20%E5%B9%B3%E5%9D%87%E8%80%97%E6%97%B6%22%5D%20--%3E%20S4%5B%22%E6%99%8B%E5%8D%87%E9%87%87%E7%BA%B3%22%5D%0A%20%20%20%20end%0A"})]),fallback:r(()=>[...t[2]||(t[2]=[a(" Loading... ",-1)])]),_:1})),t[6]||(t[6]=o('<p><strong>两条路径的差别：</strong></p><ul><li><strong>自动快通道</strong>：只要来源任务全部成功，候选方法就被直接标为「已采纳」，跳过试跑与基线对比。</li><li><strong>人工严谨通道</strong>：先记录试跑证据（要求注入过、版本一致、无外部副作用）→ 基线与试跑样本同模板、不重叠、各至少 2 个 → 按成功率与平均耗时判定「改进 / 持平 / 退步 / 证据不足」→ 判定为「改进」且样本充足才允许晋升。这一整套（含样本自动配对、拒绝、回滚）<strong>只暴露为 REST 接口，没有任何定时器或回调自动调用</strong>。虽然「任务结束后自动记录试跑证据」是接上的，但证据攒够之后没人自动触发评估。</li></ul><p><strong>另外四处「半接线」：</strong></p><ol><li><strong>记忆巩固</strong>默认 dry-run，且只有手动接口，没有定时器。</li><li><strong>方法导出成技能包</strong>只有手动接口 —— 纯自动运行时，技能索引可能长期为空。</li><li><strong>资产产生事件没有下游自动消费者</strong>，只用于界面推送、审计，以及多端同步时的冲突检测。</li><li><strong>没有专门衡量「进化是否有效」的模块</strong>：目标验收判官只判断单次任务是否达成，外部评测接口与资产链没有连接。</li></ol><p>因此严格说：<strong>「数据回流 → 证据积累」这一半是闭合的，「证据 → 评估 → 晋升」这一半靠人工驱动</strong>。</p><hr><h2 id="_8-总体评价" tabindex="-1">8. 总体评价 <a class="header-anchor" href="#_8-总体评价" aria-label="Permalink to &quot;8. 总体评价&quot;">​</a></h2><p>可以概括为：<strong>保守、以安全为先的外挂式经验系统</strong>。</p><ul><li><strong>优点</strong>：学习被严格限定在「成功样本 + 不可信建议 + 权限只收窄 + 全程可追溯可撤销」的范围内，规避了自我改进最危险的失控路径（权限扩张、跳过审批、把错误经验固化）；四类资产分层清晰，事件溯源让每一步都可解释、可回放。</li><li><strong>代价</strong>：闭环的「评估—晋升」半圈靠人工驱动，自动部分更接近<strong>经验记忆 + 流程复用</strong>，而不是会根据效果自我纠错的强化学习；也缺少「进化是否真的有效」的度量。</li></ul><p><strong>若要让闭环真正闭合，最直接的三个接线点：</strong></p><ol><li>给方法评估 / 晋升加定时调度，让攒够的试跑证据自动触发 A/B 判定；</li><li>把「已采纳」的方法自动导出成技能包，让技能索引不再依赖手动操作；</li><li>把试跑与采纳后的效果指标回流成资产评分，形成真正的优胜劣汰。</li></ol><hr><h2 id="附录-代码依据-便于核对-非代码内容" tabindex="-1">附录：代码依据（便于核对，非代码内容） <a class="header-anchor" href="#附录-代码依据-便于核对-非代码内容" aria-label="Permalink to &quot;附录：代码依据（便于核对，非代码内容）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层次</th><th>关键文件</th><th>职责一句话</th></tr></thead><tbody><tr><td>调度与装配</td><td><code>scheduler.ts</code>、<code>app.ts</code>、<code>index.ts</code></td><td>任务终态汇聚点、全部检索与注入点、服务注册与定时器启停</td></tr><tr><td>方法资产</td><td><code>methods.ts</code>、<code>method-context.ts</code></td><td>轨迹归纳、指纹判重、权限复检、评估晋升回滚；注入渲染与危险步骤过滤</td></tr><tr><td>记忆资产</td><td><code>memory.ts</code>、<code>memory-consolidation.ts</code></td><td>经验捕获、召回打分、巩固原子应用、治理门、遗忘；巩固规划纯函数</td></tr><tr><td>本体资产</td><td><code>ontology-writer.ts</code>、<code>ontology.ts</code>、<code>context-broker.ts</code></td><td>任务/审批/对话/来源写回；实体判重与冲突检测；编译个人上下文包</td></tr><tr><td>技能资产</td><td><code>skills.ts</code>、<code>skill-package.ts</code>、<code>skill-tools.ts</code>、<code>skill-permissions.ts</code>、<code>skill-curator.ts</code></td><td>方法导出、文档校验、按需加载、权限取交集、定时归档与回滚</td></tr><tr><td>数据与持久化</td><td><code>packages/core/src/types.ts</code>、<code>personal-agent.ts</code>、<code>packages/eventlog/src/database.ts</code></td><td>全部资产的类型定义、表结构与事件溯源</td></tr><tr><td>辅助注入</td><td><code>context-projector.ts</code>、<code>chat-routes.ts</code>、<code>service.ts</code>、<code>events.ts</code></td><td>交接场景注入、对话侧注入、事件总线与追加事件</td></tr></tbody></table>',14))])}const F=A(g,[["render",i]]);export{u as __pageData,F as default};
